#include <iostream>

int main() {
    // Khai bao va khoi tao / Declaration and initialization
    const int n = 10;
    int i = 2, k = n + 5;
    std::cout << "Initial i: " << i << ", k: " << k << std::endl;

    // Phep gan thong thuong / Standard assignment
    int val = 3;
    val = n / 2;
    std::cout << "val after assignment: " << val << std::endl;

    // Gan chuoi (chained assignment) / Chained assignment
    int a, b, c;
    a = b = c = 1;
    std::cout << "Chained: " << a << " " << b << " " << c << std::endl;

    // Phep gan long trong bieu thuc / Assignment embedded in expression
    int embedded_var;
    int total = 3 + (embedded_var = 2);
    std::cout << "embedded_var: " << embedded_var << ", total: " << total << std::endl;

    // Pham vi khoi lenh / Block scope demonstration
    {
        int block_scoped = 99;
        std::cout << "Inside block: " << block_scoped << std::endl;
    }

    return 0;
}

#include <iostream>

int main() {
    // Phep toan so hoc / Arithmetic operations
    std::cout << "13 / 5 = " << (13 / 5) << std::endl;
    std::cout << "13.0 / 5 = " << (13.0 / 5) << std::endl;
    std::cout << "13 % 5 = " << (13 % 5) << std::endl;
    std::cout << "5 % 13 = " << (5 % 13) << std::endl;

    // Kiem chung doc lap bang phep toan trang 33 tu i = 3, j = 15
    // Case 1: i = ++j
    int i = 3, j = 15;
    i = ++j;
    std::cout << "i = ++j -> i = " << i << ", j = " << j << std::endl;

    // Case 2: i = j++
    i = 3; j = 15;
    i = j++;
    std::cout << "i = j++ -> i = " << i << ", j = " << j << std::endl;

    // Case 3: j = ++i + 5
    i = 3; j = 15;
    j = ++i + 5;
    std::cout << "j = ++i + 5 -> i = " << i << ", j = " << j << std::endl;

    // Case 4: j = i++ + 5
    i = 3; j = 15;
    j = i++ + 5;
    std::cout << "j = i++ + 5 -> i = " << i << ", j = " << j << std::endl;

    // Phep so sanh quan he / Relational comparisons
    std::cout << "(3 == 3) -> " << (3 == 3) << std::endl;
    std::cout << "(3 == 5) -> " << (3 == 5) << std::endl;
    std::cout << "(3 != 5) -> " << (3 != 5) << std::endl;
    std::cout << "3 + (5 < 2) -> " << (3 + (5 < 2)) << std::endl;

    return 0;
}
